import itertools

def is_triangle_free(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k in adj[i]:
                    return False
    return True

def is_maximal(n, edges):
    # A graph is maximal triangle-free if it is triangle-free
    # and adding any missing edge creates a triangle.
    if not is_triangle_free(n, edges):
        return False

    all_possible_edges = list(itertools.combinations(range(n), 2))
    for edge in all_possible_edges:
        if edge not in edges and (edge[1], edge[0]) not in edges:
            # Try adding this edge
            new_edges = edges + [edge]
            if is_triangle_free(n, new_edges):
                return False
    return True

# Let's test the K_{3,4} graph
# Partition 1: {0, 1, 2}
# Partition 2: {3, 4, 5, 6}
