edges = []
for u in [0, 1, 2]:
    for v in [3, 4, 5, 6]:
        edges.append((u, v))

print(f"Is K_{3,4} triangle-free? {is_triangle_free(7, edges)}")
print(f"Is K_{3,4} maximal? {is_maximal(7, edges)}")
print(f"Edges: {edges}")

import itertools

def is_triangle_free(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k in adj[i]:
                    return False
    return True

def is_maximal(n, edges):
    if not is_triangle_free(n, edges):
        return False

    all_possible_edges = list(itertools.combinations(range(n), 2))
    for edge in all_possible_edges:
        if edge not in edges and (edge[1], edge[0]) not in edges:
            new_edges = edges + [edge]
            if is_triangle_free(n, new_edges):
                return False
    return True

# We need a maximal triangle-free graph with 7 vertices
# containing (0, 6) and (1, 5).
# Let's try to build one.
# A known maximal triangle-free graph is K_{3,4}.
# Let's see if we can map the vertices to satisfy (0, 6) and (1, 5).
# K_{3,4} has partitions A and B, |A|=3, |B|=4.
# Edges are all (a, b) with a in A, b in B.
# (0, 6) means 0 and 6 must be in different partitions.
# (1, 5) means 1 and 5 must be in different partitions.

# Let's try to assign:
# A = {0, 1, 2}
# B = {3, 4, 5, 6}
# (0, 6): 0 in A, 6 in B. This works.
# (1, 5): 1 in A, 5 in B. This works.

# So the edges are all (u, v) where u in {0, 1, 2} and v in {3, 4, 5, 6}.
edges = []
for u in [0, 1, 2]:
    for v in [3, 4, 5, 6]:
        edges.append((u, v))

print(f"Is triangle-free: {is_triangle_free(7, edges)}")
print(f"Is maximal: {is_maximal(7, edges)}")
print(f"Contains (0, 6): {(0, 6) in edges or (6, 0) in edges}")
print(f"Contains (1, 5): {(1, 5) in edges or (5, 1) in edges}")
print(f"Edges: {edges}")
